using System;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Collections.Generic;
using System.Text;
using System.Xml.Linq;

namespace DoonPanelPreview {
 public static class SelfTests {
  static int count;static void Check(bool ok,string name){count++;if(!ok)throw new Exception("Test failed: "+name);}
  static readonly XNamespace N="http://schemas.openxmlformats.org/spreadsheetml/2006/main";
  static XElement Cell(string a,string v,bool number=false){return number?new XElement(N+"c",new XAttribute("r",a),new XAttribute("s",1),new XElement(N+"v",v)):new XElement(N+"c",new XAttribute("r",a),new XAttribute("t","inlineStr"),new XElement(N+"is",new XElement(N+"t",v)));}
  public static byte[] Workbook(bool changed=false){using(var mem=new MemoryStream()){using(var z=new ZipArchive(mem,ZipArchiveMode.Create,true)){
   Action<string,string> add=(path,xml)=>{var entry=z.CreateEntry(path);entry.LastWriteTime=new DateTimeOffset(2026,1,1,0,0,0,TimeSpan.Zero);using(var s=new StreamWriter(entry.Open(),new UTF8Encoding(false)))s.Write(xml);};
   add("xl/workbook.xml","<workbook xmlns='"+N+"' xmlns:r='http://schemas.openxmlformats.org/officeDocument/2006/relationships'><sheets><sheet name='PI' sheetId='1' r:id='rId1'/></sheets></workbook>");add("xl/_rels/workbook.xml.rels","<Relationships xmlns='http://schemas.openxmlformats.org/package/2006/relationships'><Relationship Id='rId1' Target='worksheets/sheet1.xml' Type='http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet'/></Relationships>");
   add("xl/styles.xml","<styleSheet xmlns='"+N+"'><numFmts count='1'><numFmt numFmtId='164' formatCode='&quot;US$&quot;0.00'/></numFmts><cellXfs count='2'><xf numFmtId='0'/><xf numFmtId='164'/></cellXfs></styleSheet>");
   var data=new XElement(N+"sheetData",new XElement(N+"row",new XAttribute("r",1),Cell("A1","PI No."),Cell("B1","2026-C999-001")),new XElement(N+"row",new XAttribute("r",2),new[]{"No","Drawing","Model","Colourway","Order qty","Unit","Frame price","Remarks"}.Select((s,i)=>Cell(XlsxSource.Address(2,i+1),s))),new XElement(N+"row",new XAttribute("r",3),Cell("A3","1"),Cell("B3"," DN 9001-AC "),Cell("C3","TEST 001"),Cell("D3","C01"),Cell("E3","10",true),Cell("F3","PCS"),Cell("G3",changed?"13":"12.5",true),Cell("H3","already included")),new XElement(N+"row",new XAttribute("r",4),Cell("A4","2"),Cell("D4","C02"),Cell("E4","2",true),Cell("F4","PCS"),Cell("G4","0",true)));
   add("xl/worksheets/sheet1.xml",new XElement(N+"worksheet",data,new XElement(N+"mergeCells",new XElement(N+"mergeCell",new XAttribute("ref","B3:B4")),new XElement(N+"mergeCell",new XAttribute("ref","C3:C4")))).ToString());
  }return mem.ToArray();}}
  static byte[] MaterialsWorkbook(){using(var input=new MemoryStream(Workbook()))using(var zin=new ZipArchive(input,ZipArchiveMode.Read))using(var output=new MemoryStream()){using(var zout=new ZipArchive(output,ZipArchiveMode.Create,true)){foreach(var entry in zin.Entries){using(var dest=zout.CreateEntry(entry.FullName).Open()){if(entry.FullName!="xl/worksheets/sheet1.xml"){using(var source=entry.Open())source.CopyTo(dest);}else{var data=new XElement(N+"sheetData",new XElement(N+"row",new XAttribute("r",1),new[]{"物料编码","物料名称","规格型号","基本单位","物料分类","不应入库字段"}.Select((s,i)=>Cell(XlsxSource.Address(1,i+1),s))));for(int r=2;r<=3;r++)data.Add(new XElement(N+"row",new XAttribute("r",r),Cell("A"+r,r==2?" 00 TEST +1 ":"00TEST+1"),Cell("B"+r,"合成物料"),Cell("C"+r,"SYNTH"),Cell("D"+r,"PCS"),Cell("E"+r,"合成分类"),Cell("F"+r,"不得进入字段载荷")));using(var writer=new StreamWriter(dest,new UTF8Encoding(false)))writer.Write(new XElement(N+"worksheet",data).ToString());}}}}return output.ToArray();}}
  static PriceRow Copy(PriceRow p){return PriceParser.Json.Deserialize<PriceRow>(PriceParser.Json.Serialize(p));}
  public static string Run(){count=0;var parsed=PriceParser.Parse(Workbook(),"synthetic.xlsx");Check(parsed.Rows.Count==2,"rows and merged anchors");var p=parsed.Rows[0];Check(p.Customer=="C999"&&p.Drawing=="DN9001"&&p.Model=="TEST001","customer and whitespace normalization");Check(p.Currency=="USD"&&p.UnitPrice=="12.5"&&p.Status=="可匹配","price currency");Check(parsed.Rows[1].Status.Contains("零价"),"zero is explicit");Check(parsed.Rows[1].Drawing==p.Drawing,"merged drawing");
   var order=Copy(p);order.BasePrice="";order.UnitPrice="";order.Pi="2027-C999-001";Check(PriceMatcher.Match(order,parsed.Rows).Amount=="125","missing order price calculated");var other=Copy(p);other.UnitPrice="13";Check(PriceMatcher.Match(order,new[]{p,other}).Status=="价格冲突","conflict not first-match");order.Pi=p.Pi;other.Pi="2025-C999-009";Check(PriceMatcher.Match(order,new[]{p,other}).Price=="12.5","same PI preference");order.Customer="C998";Check(PriceMatcher.Match(order,new[]{p}).Status=="未匹配","customer isolation");order=Copy(p);order.Kind="样办";Check(PriceMatcher.Match(order,new[]{p}).Status=="未匹配","sample isolation");order=Copy(p);order.UnitPrice="99";Check(PriceMatcher.Match(order,new[]{p}).Status=="原单价格不同","existing price not overwritten");order=Copy(p);order.Status="识别字段含公式待核对";Check(PriceMatcher.Match(order,new[]{p}).Status=="待确认","formula cache not trusted");order=Copy(p);other=Copy(p);other.Status="零价需确认";other.UnitPrice="0";Check(PriceMatcher.Match(order,new[]{p,other}).Status=="待确认","zero duplicate blocks");order=Copy(p);order.Quantity="-1";Check(PriceMatcher.Match(order,new[]{p}).Status=="待确认","negative quantity");order=Copy(p);order.Currency="CNY";Check(PriceMatcher.Match(order,new[]{p}).Status=="待确认","currency mismatch");
   string root=Path.Combine(Path.GetTempPath(),"doon-price-test-"+Guid.NewGuid().ToString("N"));try{using(var db=new PriceStore(root)){Check(db.Import(parsed)==2,"insert");Check(db.Import(parsed)==0,"idempotent");Check(db.All().Count==2,"persisted count");var update=PriceParser.Parse(Workbook(true),"synthetic.xlsx");Check(db.Import(update)==2&&db.All().Count==4,"revised source appends");string copy=Path.Combine(root,"copy.xlsx");db.CopyOriginal(p,copy);Check(PriceParser.Hash(File.ReadAllBytes(copy))==parsed.Hash,"original byte fidelity");Check(db.Integrity()=="ok","sqlite integrity");string names=Path.Combine(root,"names.json");File.WriteAllText(names,PriceParser.Json.Serialize(new[]{new ProductName{Code=" TEST ",Name="合成名称",Source="合成依据"},new ProductName{Code="合成材质",Name="合成名称",Source="合成别名依据"}}));Check(db.ImportNames(names)==2,"name rules import");Check(db.ImportNames(names)==0,"name rules idempotent");var materials=MaterialParser.Parse(MaterialsWorkbook(),"synthetic-materials.xlsx");Check(materials.Rows.Count==2&&materials.Rows[0].Values.Count==5,"only five material fields");Check(materials.Rows[0].Code=="00TEST+1"&&materials.Rows[0].Values["物料编码"]==" 00 TEST +1 ","original code and normalized index");Check(db.ImportMaterials(materials)==2&&db.ImportMaterials(materials)==0,"material import idempotent");Check(db.Materials().Count==2&&db.Materials().All(m=>m.Values.Count==5),"duplicate material codes retained");Check(db.All().Count==4,"material import leaves prices unchanged");Check(db.Names().Any(n=>n.Code=="TEST")&&db.Names().Any(n=>n.Code=="合成材质"),"name and alias normalization");}using(var db=new PriceStore(root))Check(db.All().Count==4,"reopen persistence");}finally{string absolute=Path.GetFullPath(root);if(absolute.StartsWith(Path.GetFullPath(Path.GetTempPath()),StringComparison.OrdinalIgnoreCase)&&Path.GetFileName(absolute).StartsWith("doon-price-test-"))Directory.Delete(absolute,true);}
   return "PASS "+(count+CodingTests.Run()+ExportTests.Run())+" synthetic assertions";
  }
 }
}
